1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Scenario {
6	  customer: Customer;
7	  steps: Step[];
8	}
9	
10	export type Step = QuoteStep | ClaimStep;
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Item {
18	  type: string;
19	  material?: string;
20	  enchantment?: number;
21	  cursed?: boolean;
22	}
23	
24	export interface ClaimStep {
25	  op: "claim";
26	  policy: number;
27	  incident: Incident;
28	}
29	
30	export interface Incident {
31	  cause: string;
32	  damages: Damage[];
33	}
34	
35	export interface Damage {
36	  itemType: string;
37	  amount: number;
38	}
39	
40	export type StepResult = { premium: number } | { payout: number; remainingCap: number };
41	
42	export interface ScenarioResult {
43	  results: StepResult[];
44	}
45	
46	const PROCESSING_FEE = 5;
47	
48	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
49	  sword: 100,
50	  amulet: 60,
51	  staff: 80,
52	  potion: 40,
53	  rune: 25,
54	  moonstone: 25,
55	};
56	
57	const INSURANCE_VALUE_BY_ITEM_TYPE: Record<string, number> = {
58	  sword: 1000,
59	  amulet: 600,
60	  staff: 800,
61	  potion: 400,
62	  rune: 250,
63	  moonstone: 250,
64	};
65	
66	const DEDUCTIBLE_PER_DAMAGE = 100;
67	const CAP_MULTIPLE = 2;
68	const ALIKE_ITEMS_PER_BLOCK = 3;
69	const BLOCK_BASE_PREMIUM = 60;
70	const CURSE_SURCHARGE_RATE = 0.5;
71	const HIGH_ENCHANTMENT_LEVEL = 5;
72	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
73	const LOYALTY_YEARS_THRESHOLD = 2;
74	const LOYALTY_DISCOUNT_RATE = 0.2;
75	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
76	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
77	
78	const sum = (amounts: number[]): number =>
79	  amounts.reduce((total, amount) => total + amount, 0);
80	
81	const groupByType = (items: Item[]): Item[][] => {
82	  const itemsByType = new Map<string, Item[]>();
83	
84	  for (const item of items) {
85	    const alikeItems = itemsByType.get(item.type);
86	    if (alikeItems) alikeItems.push(item);
87	    else itemsByType.set(item.type, [item]);
88	  }
89	
90	  return [...itemsByType.values()];
91	};
92	
93	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_ITEM_TYPE[item.type];
94	
95	const basePremiumOfAlikeItems = (alikeItems: Item[]): number =>
96	  alikeItems.length === ALIKE_ITEMS_PER_BLOCK
97	    ? BLOCK_BASE_PREMIUM
98	    : sum(alikeItems.map(basePremiumOf));
99	
100	const curseSurchargeOf = (item: Item): number =>
101	  item.cursed ? basePremiumOf(item) * CURSE_SURCHARGE_RATE : 0;
102	
103	const highEnchantmentSurchargeOf = (item: Item): number =>
104	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL
105	    ? basePremiumOf(item) * HIGH_ENCHANTMENT_SURCHARGE_RATE
106	    : 0;
107	
108	const itemSurchargesOf = (item: Item): number =>
109	  curseSurchargeOf(item) + highEnchantmentSurchargeOf(item);
110	
111	// Policy-wide adjustments are rates on the base premium: surcharges are
112	// positive, discounts negative. Each applies only when its condition holds.
113	const policyAdjustmentRatesOf = (customer: Customer, isFollowUpQuote: boolean): number[] => [
114	  FIRST_INSURANCE_SURCHARGE_RATE,
115	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD ? -LOYALTY_DISCOUNT_RATE : 0,
116	  isFollowUpQuote ? -FOLLOW_UP_DISCOUNT_RATE : 0,
117	];
118	
119	const quote = (
120	  { items }: QuoteStep,
121	  customer: Customer,
122	  isFollowUpQuote: boolean,
123	): StepResult => {
124	  const basePremium = sum(groupByType(items).map(basePremiumOfAlikeItems));
125	  const itemSurcharges = sum(items.map(itemSurchargesOf));
126	  const policyAdjustments =
127	    basePremium * sum(policyAdjustmentRatesOf(customer, isFollowUpQuote));
128	
129	  return {
130	    premium: Math.ceil(basePremium + itemSurcharges + policyAdjustments + PROCESSING_FEE),
131	  };
132	};
133	
134	const insuranceValueOf = (item: Item): number => INSURANCE_VALUE_BY_ITEM_TYPE[item.type];
135	
136	const insuranceSumOf = (items: Item[]): number => sum(items.map(insuranceValueOf));
137	
138	const claim = ({ incident }: ClaimStep, policyItems: Item[]): StepResult => {
139	  const payout = sum(
140	    incident.damages.map((damage) => damage.amount - DEDUCTIBLE_PER_DAMAGE),
141	  );
142	  const cap = insuranceSumOf(policyItems) * CAP_MULTIPLE;
143	
144	  return { payout: Math.floor(payout), remainingCap: cap - payout };
145	};
146	
147	export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => {
148	  const policyItemsByStep = new Map<number, Item[]>();
149	  let quotesSoFar = 0;
150	
151	  const results = steps.map((step, stepIndex) => {
152	    if (step.op === "claim") {
153	      return claim(step, policyItemsByStep.get(step.policy) ?? []);
154	    }
155	
156	    policyItemsByStep.set(stepIndex, step.items);
157	    const result = quote(step, customer, quotesSoFar > 0);
158	    quotesSoFar += 1;
159	
160	    return result;
161	  });
162	
163	  return { results };
164	};
